21	// ruleChangeEvidence 刻意包含中文、换行与前后空白；定义变化不得改写旧证据。
22	const ruleChangeEvidence = "  旧反例：调用顺序如下\n  attacker.withdraw() 再入  "
23	
24	// ruleChangeBaseRule 是基准侧规则定义；每个漂移用例只改其中一个字段。
25	func ruleChangeBaseRule() Rule {
26		return Rule{
27			ID:          "reentrancy-guard",
28			Kind:        "static",
29			Severity:    "high",
30			Invariant:   "no-reentrant-withdraw",
31			RequiresABI: false,
32			Version:     "3.1.0",
33		}
34	}
35	
36	// saveRuleChangeCheckReport 通过外部检查记录落盘一份单规则报告：基准侧保留
37	// 具体反例，新侧记录通过。证据中的中文、换行和前后空白随检查说明原样归档。
38	func saveRuleChangeCheckReport(t *testing.T, dir string, artifact Artifact, rule Rule, status string, note string) Report {
39		t.Helper()
40		report := saveCheckReport(t, dir, artifact, []Rule{rule}, []CheckRecord{{
41			ArtifactHash: ArtifactHash(artifact),
42			RuleID:       rule.ID,
43			Version:      rule.Version,
44			Status:       status,
45			Note:         note,
46		}})
