1	package contractsentinel
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件回归保护“缺陷仍然存在，但检查器更新了反例说明”的比较场景：两侧都是
11	// “发现缺陷”、规则定义（标识、版本及其余字段）完全一致、只有说明原文不同时，
12	// 必须归为“检查说明变化”，而不能把证据更新误解释成新增或消除缺陷。两侧的
13	// 缺陷证据各自保留当次归档的反例原文，仍绑定原产物哈希、规则标识与版本。
14	// 既有说明变化用例（TestDiffNoteChange）覆盖的是“通过”状态，这里保护缺陷状态。
15	
16	// 两次检查各自的反例说明：中文、换行与前后空格都属于说明内容。
17	const (
18		defectNoteBefore = "反例：攻击者先存入 1 ether 后调用 withdraw；\n  call 在 balances 扣减前交出控制权，receive 重入，同一笔余额被第二次转出。"
19		defectNoteAfter  = "反例（更新）：攻击合约 receive 在 balances 扣减前重入 withdraw；\n  此时 balances[msg.sender] 仍是旧值，同一笔余额被第二次转出。"
20	)
21	
22	// defectNoteRules 是两侧共用的一份规则定义，标识、版本及其余字段完全一致。
23	func defectNoteRules() []Rule {
24		return []Rule{{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.2"}}
25	}
26	
27	func defectCheck(hash, note string) CheckRecord {
28		return CheckRecord{ArtifactHash: hash, RuleID: "reentrancy-guard", Version: "1.4.2", Status: StatusDefect, Note: note}
29	}
30	
31	// 核心场景：同一产物、同一条带版本规则，两侧都“发现缺陷”，仅反例说明不同。
32	// 该规则只出现一次并归为“检查说明变化”；新增/消除缺陷与状态变化均为零，
33	// 两侧缺陷总数各为一；两份原始证据分别留在各自一侧，不交换、不拼接。
34	func TestDiffDefectNoteUpdatedKeepsBothEvidences(t *testing.T) {
35		dir := t.TempDir()
36		artifact := sampleArtifact()
37		hash := ArtifactHash(artifact)
38		rules := defectNoteRules()
39		before := saveCheckReport(t, dir, artifact, rules, []CheckRecord{defectCheck(hash, defectNoteBefore)})
40		after := saveCheckReport(t, dir, artifact, rules, []CheckRecord{defectCheck(hash, defectNoteAfter)})
41	
42		// 说明不同则报告内容不同，两份报告必须具有不同的报告标识。
43		if before.ReportID == after.ReportID {
44			t.Fatal("reports with different notes must have different report ids")
45		}
46	
47		// 比较全程不得改动归档：先记录目录内容快照。
48		filesBefore := storeFileNames(t, dir)
49		contentsBefore := map[string]string{}
50		for _, name := range filesBefore {
51			data, err := os.ReadFile(filepath.Join(dir, name))
52			if err != nil {
53				t.Fatal(err)
54			}
55			contentsBefore[name] = string(data)
56		}
57	
58		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
59		if err != nil {
60			t.Fatal(err)
61		}
62	
63		// 基准侧与新侧分别引用各自报告。
64		if diff.Before.ReportID != before.ReportID || diff.After.ReportID != after.ReportID {
65			t.Errorf("refs = %q/%q, want %q/%q", diff.Before.ReportID, diff.After.ReportID, before.ReportID, after.ReportID)
66		}
67		if diff.ArtifactNameChanged || diff.ArtifactHashChanged {
68			t.Error("same artifact must not be flagged as changed")
69		}
70	
71		// 这条规则只出现一次，归为“检查说明变化”。
72		if len(diff.Results) != 1 {
73			t.Fatalf("results = %d, want 1", len(diff.Results))
74		}
75		entry := diff.Results[0]
76		if entry.RuleID != "reentrancy-guard" {
77			t.Fatalf("rule id = %q", entry.RuleID)
78		}
79		if entry.Change != ChangeNoteChanged {
80			t.Fatalf("change = %q, want %q", entry.Change, ChangeNoteChanged)
81		}
82	
83		// 汇总：说明变化一条；新增缺陷、已消除缺陷、检查状态变化均为零；
84		// 两侧缺陷总数各为一（证据更新不是缺陷的增减）。
85		s := diff.Summary
86		if s.NoteChanges != 1 {
87			t.Errorf("noteChanges = %d, want 1", s.NoteChanges)
88		}
89		if s.NewDefects != 0 || s.ResolvedDefects != 0 || s.StatusChanges != 0 {
90			t.Errorf("evidence update must not count as defect or status change: %+v", s)
91		}
92		if s.NoChange != 0 || s.AddedRules != 0 || s.RemovedRules != 0 || s.ChangedRules != 0 {
93			t.Errorf("unexpected counts: %+v", s)
94		}
95		if s.BeforeDefects != 1 || s.AfterDefects != 1 {
96			t.Errorf("defect totals = %d/%d, want 1/1", s.BeforeDefects, s.AfterDefects)
97		}
98	
99		// 基准侧保留旧反例，新侧保留新反例；两侧缺陷仍绑定原来的产物哈希、
100		// 规则标识与版本。旧侧证据不能换成新侧文字，两份说明也不能拼成一份证据。
101		if entry.Before == nil || entry.After == nil {
102			t.Fatal("both sides must be present")
103		}
104		if entry.Before.Rule.Status != StatusDefect || entry.After.Rule.Status != StatusDefect {
105			t.Errorf("statuses = %q/%q, both must be %q", entry.Before.Rule.Status, entry.After.Rule.Status, StatusDefect)
106		}
107		if entry.Before.Rule.Note != defectNoteBefore {
108			t.Errorf("before note = %q, want the old counterexample verbatim", entry.Before.Rule.Note)
109		}
110		if entry.After.Rule.Note != defectNoteAfter {
111			t.Errorf("after note = %q, want the new counterexample verbatim", entry.After.Rule.Note)
112		}
113		if entry.Before.Finding == nil || entry.After.Finding == nil {
114			t.Fatal("both defect sides must carry their findings")
115		}
116		bf, af := entry.Before.Finding, entry.After.Finding
117		if bf.Evidence != defectNoteBefore {
118			t.Errorf("before evidence = %q, want the old counterexample verbatim", bf.Evidence)
119		}
120		if af.Evidence != defectNoteAfter {
121			t.Errorf("after evidence = %q, want the new counterexample verbatim", af.Evidence)
122		}
123		for side, f := range map[string]*ReportFinding{"before": bf, "after": af} {
124			if f.ArtifactHash != hash || f.RuleID != "reentrancy-guard" || f.Version != "1.4.2" {
125				t.Errorf("%s finding binding = %+v, want hash=%q rule=reentrancy-guard version=1.4.2", side, *f, hash)
126			}
127		}
128		if strings.Contains(bf.Evidence, defectNoteAfter) || strings.Contains(af.Evidence, defectNoteBefore) {
129			t.Error("evidences must not be swapped or merged into one")
130		}
131	
132		// 比较后的归档内容保持原样。
133		filesAfter := storeFileNames(t, dir)
134		if strings.Join(filesBefore, ",") != strings.Join(filesAfter, ",") {
135			t.Fatalf("store files changed: %v -> %v", filesBefore, filesAfter)
136		}
137		for _, name := range filesAfter {
138			data, err := os.ReadFile(filepath.Join(dir, name))
139			if err != nil {
140				t.Fatal(err)
141			}
142			if string(data) != contentsBefore[name] {
143				t.Errorf("diff modified archive %s", name)
144			}
145		}
146	
147		// 读回任一报告仍能看到该次检查保存的反例。
148		reloadedBefore, err := LoadReport(dir, before.ReportID)
149		if err != nil {
150			t.Fatal(err)
151		}
152		reloadedAfter, err := LoadReport(dir, after.ReportID)
153		if err != nil {
154			t.Fatal(err)
155		}
156		if reloadedBefore.Rules[0].Note != defectNoteBefore || reloadedBefore.Findings[0].Evidence != defectNoteBefore {
157			t.Errorf("reloaded before report lost its counterexample: %+v / %+v", reloadedBefore.Rules[0], reloadedBefore.Findings[0])
158		}
159		if reloadedAfter.Rules[0].Note != defectNoteAfter || reloadedAfter.Findings[0].Evidence != defectNoteAfter {
160			t.Errorf("reloaded after report lost its counterexample: %+v / %+v", reloadedAfter.Rules[0], reloadedAfter.Findings[0])
161		}
162	}
163	
164	// 说明按原文比较：仅增加一个尾随空格也属于说明变化，两侧文字逐字保留。
165	func TestDiffDefectNoteTrailingSpaceIsNoteChange(t *testing.T) {
166		dir := t.TempDir()
167		artifact := sampleArtifact()
168		hash := ArtifactHash(artifact)
169		rules := defectNoteRules()
170		base := "反例：重入路径仍可达\n  第二行证据"
171		before := saveCheckReport(t, dir, artifact, rules, []CheckRecord{defectCheck(hash, base)})
172		after := saveCheckReport(t, dir, artifact, rules, []CheckRecord{defectCheck(hash, base+" ")})
173	
174		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
175		if err != nil {
176			t.Fatal(err)
177		}
178		if len(diff.Results) != 1 || diff.Results[0].Change != ChangeNoteChanged {
179			t.Fatalf("a trailing space is a note change: %+v", diff.Results)
180		}
181		if diff.Summary.NoteChanges != 1 || diff.Summary.NoChange != 0 {
182			t.Errorf("summary = %+v", diff.Summary)
183		}
184		if diff.Summary.BeforeDefects != 1 || diff.Summary.AfterDefects != 1 {
185			t.Errorf("defect totals = %d/%d, want 1/1", diff.Summary.BeforeDefects, diff.Summary.AfterDefects)
186		}
187		entry := diff.Results[0]
188		if entry.Before.Rule.Note != base || entry.Before.Finding.Evidence != base {
189			t.Errorf("before side must keep the note verbatim without trailing space: %q", entry.Before.Rule.Note)
190		}
191		if entry.After.Rule.Note != base+" " || entry.After.Finding.Evidence != base+" " {
192			t.Errorf("after side must keep the trailing space verbatim: %q", entry.After.Rule.Note)
193		}
194	}
195	
196	// 原文完全相同（同一份报告在两侧）则归为“无变化”，不增加说明变化计数。
197	func TestDiffDefectIdenticalNoteIsNoChange(t *testing.T) {
198		dir := t.TempDir()
199		artifact := sampleArtifact()
200		hash := ArtifactHash(artifact)
201		report := saveCheckReport(t, dir, artifact, defectNoteRules(), []CheckRecord{defectCheck(hash, defectNoteBefore)})
202	
203		diff, err := DiffStore(dir, report.ReportID, report.ReportID)
204		if err != nil {
205			t.Fatal(err)
206		}
207		if len(diff.Results) != 1 || diff.Results[0].Change != ChangeNoChange {
208			t.Fatalf("identical notes must be no change: %+v", diff.Results)
209		}
210		s := diff.Summary
211		if s.NoteChanges != 0 || s.NewDefects != 0 || s.ResolvedDefects != 0 || s.StatusChanges != 0 {
212			t.Errorf("identical evidence must not fabricate changes: %+v", s)
213		}
214		if s.NoChange != 1 || s.BeforeDefects != 1 || s.AfterDefects != 1 {
215			t.Errorf("summary = %+v, want noChange=1 defects=1/1", s)
216		}
217		entry := diff.Results[0]
218		if entry.Before.Finding == nil || entry.After.Finding == nil ||
219			entry.Before.Finding.Evidence != defectNoteBefore || entry.After.Finding.Evidence != defectNoteBefore {
220			t.Errorf("both sides must keep the same evidence: %+v / %+v", entry.Before.Finding, entry.After.Finding)
221		}
222	}
223	
224	// 分类边界：两侧都发现缺陷且说明不同，但规则版本已变化时仍归为“规则变化”，
225	// 不同时计为说明变化；两侧各自保留自己的反例证据与版本绑定。
226	func TestDiffDefectNoteChangeWithVersionBumpIsRuleChange(t *testing.T) {
227		dir := t.TempDir()
228		artifact := sampleArtifact()
229		hash := ArtifactHash(artifact)
230		before := saveCheckReport(t, dir, artifact, defectNoteRules(),
231			[]CheckRecord{defectCheck(hash, defectNoteBefore)})
232		afterRules := []Rule{{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.3"}}
233		after := saveCheckReport(t, dir, artifact, afterRules,
234			[]CheckRecord{{ArtifactHash: hash, RuleID: "reentrancy-guard", Version: "1.4.3", Status: StatusDefect, Note: defectNoteAfter}})
235	
236		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
237		if err != nil {
238			t.Fatal(err)
239		}
240		if len(diff.Results) != 1 || diff.Results[0].Change != ChangeRuleChanged {
241			t.Fatalf("version bump must stay 规则变化: %+v", diff.Results)
242		}
243		s := diff.Summary
244		if s.ChangedRules != 1 || s.NoteChanges != 0 {
245			t.Errorf("changedRules = %d, noteChanges = %d, want 1/0", s.ChangedRules, s.NoteChanges)
246		}
247		if s.NewDefects != 0 || s.ResolvedDefects != 0 || s.StatusChanges != 0 {
248			t.Errorf("rule change must not count as defect or status change: %+v", s)
249		}
250		if s.BeforeDefects != 1 || s.AfterDefects != 1 {
251			t.Errorf("defect totals = %d/%d, want 1/1", s.BeforeDefects, s.AfterDefects)
252		}
253		entry := diff.Results[0]
254		if entry.Before.Finding == nil || entry.Before.Finding.Evidence != defectNoteBefore ||
255			entry.Before.Finding.Version != "1.4.2" {
256			t.Errorf("before side must keep the old evidence at the old version: %+v", entry.Before.Finding)
257		}
258		if entry.After.Finding == nil || entry.After.Finding.Evidence != defectNoteAfter ||
259			entry.After.Finding.Version != "1.4.3" {
260			t.Errorf("after side must keep the new evidence at the new version: %+v", entry.After.Finding)
261		}
262	}
263	
264	// 同一份比较中的不同规则互不影响：一条规则更新反例，另一条保留原有缺陷
265	// 证据时后者保持“无变化”；两侧缺陷总数各为二，说明变化仍只有一条。两份
266	// 归档中规则与缺陷的排列刻意不同，输出必须按规则标识关联各自的证据。
267	func TestDiffDefectNoteChangeMatchesEvidenceByRuleID(t *testing.T) {
268		dir := t.TempDir()
269		artifact := sampleArtifact()
270		hash := ArtifactHash(artifact)
271		stableNote := "反例：owner 校验缺失，任意账户可调用 withdraw。"
272		updatedRule := Rule{ID: "reentrancy-guard", Kind: "static", Severity: "high", Invariant: "no-reentrant-withdraw", Version: "1.4.2"}
273		stableRule := Rule{ID: "owner-only-withdraw", Kind: "static", Severity: "medium", Invariant: "withdraw-owner-only", Version: "2.1.0"}
274		updatedCheck := func(note string) CheckRecord {
275			return CheckRecord{ArtifactHash: hash, RuleID: updatedRule.ID, Version: updatedRule.Version, Status: StatusDefect, Note: note}
276		}
277		stableCheck := CheckRecord{ArtifactHash: hash, RuleID: stableRule.ID, Version: stableRule.Version, Status: StatusDefect, Note: stableNote}
278	
279		// 两侧规则与 checks 的提交排列刻意相反，归档中的数组顺序因此不同。
280		before := saveCheckReport(t, dir, artifact,
281			[]Rule{updatedRule, stableRule},
282			[]CheckRecord{updatedCheck(defectNoteBefore), stableCheck})
283		after := saveCheckReport(t, dir, artifact,
284			[]Rule{stableRule, updatedRule},
285			[]CheckRecord{stableCheck, updatedCheck(defectNoteAfter)})
286	
287		diff, err := DiffStore(dir, before.ReportID, after.ReportID)
288		if err != nil {
289			t.Fatal(err)
290		}
291		if len(diff.Results) != 2 {
292			t.Fatalf("results = %d, want 2", len(diff.Results))
293		}
294		byID := map[string]RuleDiff{}
295		for _, r := range diff.Results {
296			byID[r.RuleID] = r
297		}
298	
299		// 更新反例的规则归为“检查说明变化”，两侧证据各自保留。
300		updated := byID[updatedRule.ID]
301		if updated.Change != ChangeNoteChanged {
302			t.Errorf("updated rule change = %q, want %q", updated.Change, ChangeNoteChanged)
303		}
304		if updated.Before.Finding == nil || updated.Before.Finding.Evidence != defectNoteBefore ||
305			updated.After.Finding == nil || updated.After.Finding.Evidence != defectNoteAfter {
306			t.Errorf("updated rule evidences = %+v / %+v", updated.Before.Finding, updated.After.Finding)
307		}
308	
309		// 保留原有证据的规则保持“无变化”，其证据不能按数组位置串到另一条规则。
310		stable := byID[stableRule.ID]
311		if stable.Change != ChangeNoChange {
312			t.Errorf("stable rule change = %q, want %q", stable.Change, ChangeNoChange)
313		}
314		if stable.Before.Finding == nil || stable.Before.Finding.Evidence != stableNote ||
315			stable.After.Finding == nil || stable.After.Finding.Evidence != stableNote {
316			t.Errorf("stable rule evidences = %+v / %+v, want %q on both sides",
317				stable.Before.Finding, stable.After.Finding, stableNote)
318		}
319		if stable.Before.Rule.Note != stableNote || stable.After.Rule.Note != stableNote {
320			t.Errorf("stable rule notes = %q / %q", stable.Before.Rule.Note, stable.After.Rule.Note)
321		}
322		for side, f := range map[string]*ReportFinding{"before": stable.Before.Finding, "after": stable.After.Finding} {
323			if f.RuleID != stableRule.ID || f.Version != stableRule.Version || f.ArtifactHash != hash {
324				t.Errorf("stable %s finding binding = %+v", side, *f)
325			}
326		}
327	
328		// 汇总：说明变化仍只有一条；两侧缺陷总数各为二。
329		s := diff.Summary
330		if s.NoteChanges != 1 || s.NoChange != 1 {
331			t.Errorf("noteChanges/noChange = %d/%d, want 1/1", s.NoteChanges, s.NoChange)
332		}
333		if s.NewDefects != 0 || s.ResolvedDefects != 0 || s.StatusChanges != 0 || s.ChangedRules != 0 {
334			t.Errorf("unexpected counts: %+v", s)
335		}
336		if s.BeforeDefects != 2 || s.AfterDefects != 2 {
337			t.Errorf("defect totals = %d/%d, want 2/2", s.BeforeDefects, s.AfterDefects)
338		}
339	
340		// 比较后读回两份归档，各自仍能看到该次检查保存的两条反例。
341		reloadedBefore, err := LoadReport(dir, before.ReportID)
342		if err != nil {
343			t.Fatal(err)
344		}
345		reloadedAfter, err := LoadReport(dir, after.ReportID)
346		if err != nil {
347			t.Fatal(err)
348		}
349		evidenceByRule := func(r Report) map[string]string {
350			out := map[string]string{}
351			for _, f := range r.Findings {
352				out[f.RuleID] = f.Evidence
353			}
354			return out
355		}
356		beforeEvidence := evidenceByRule(reloadedBefore)
357		if beforeEvidence[updatedRule.ID] != defectNoteBefore || beforeEvidence[stableRule.ID] != stableNote {
358			t.Errorf("reloaded before evidences = %v", beforeEvidence)
359		}
360		afterEvidence := evidenceByRule(reloadedAfter)
361		if afterEvidence[updatedRule.ID] != defectNoteAfter || afterEvidence[stableRule.ID] != stableNote {
362			t.Errorf("reloaded after evidences = %v", afterEvidence)
363		}
364	}
