337			t.Errorf("reversed z-new-defect = %q, want %q", changeByID["z-new-defect"], contractsentinel.ChangeResolvedDefect)
338		}
339		if changeByID["a-resolved"] != contractsentinel.ChangeNewDefect {
340			t.Errorf("reversed a-resolved = %q, want %q", changeByID["a-resolved"], contractsentinel.ChangeNewDefect)
341		}
342		if d.Summary.NewDefects != 1 || d.Summary.ResolvedDefects != 1 {
343			t.Errorf("reversed summary = %+v", d.Summary)
344		}
345	}
346	
347	// 同一对报告重复比较必须给出字节一致的结果，命令行输出确定可复现。
348	func TestCLIDiffDeterministicOutput(t *testing.T) {
349		bin := auditBinary(t)
350		work := t.TempDir()
351		store := filepath.Join(work, "reports")
352		artifact := mixedCheckArtifact()
353		hash := mixedArtifactHash(t)
354		rules := diffRules()
355		before := auditDiffReport(t, bin, work, store, "before.json", artifact, rules, diffBeforeChecks(hash))
356		after := auditDiffReport(t, bin, work, store, "after.json", artifact, rules, diffAfterChecks(hash))
357	
358		first, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
359		if code != 0 {
360			t.Fatal("first diff must succeed")
361		}
362		second, _, code := runCLIDiff(t, bin, store, before.ReportID, after.ReportID)
363		if code != 0 {
364			t.Fatal("second diff must succeed")
365		}
366		if first != second {
367			t.Fatal("repeated diffs must render byte-identical output")
368		}
369		// 比较结果不得携带任何时间戳字段（规则 id 中的 "timeout" 字样不算）。
370		for _, key := range []string{`"time"`, `"date"`, `"timestamp"`, `"createdAt"`} {
371			if strings.Contains(first, key) {
372				t.Errorf("diff output must not contain timestamp field %s", key)
373			}
374		}
375	}
376	
377	// 任一报告不存在：非零退出、原因进 stderr、stdout 完全空白；第二份报告
378	// 出错时也不得把已读到的第一份报告当作成功结果输出。
379	func TestCLIDiffMissingReportFailsCleanly(t *testing.T) {
380		bin := auditBinary(t)
381		work := t.TempDir()
382		store := filepath.Join(work, "reports")
383		artifact := mixedCheckArtifact()
384		hash := mixedArtifactHash(t)
385		rules := diffRules()
386		existing := auditDiffReport(t, bin, work, store, "only.json", artifact, rules, diffAfterChecks(hash))
387		missing := strings.Repeat("0", 64)
388	
389		cases := []struct {
390			name   string
391			before string
392			after  string
393		}{
394			{"before missing", missing, existing.ReportID},
395			{"after missing", existing.ReportID, missing},
396			{"both missing", strings.Repeat("1", 64), missing},
397		}
398		for _, tc := range cases {
399			t.Run(tc.name, func(t *testing.T) {
400				stdout, stderr, code := runCLIDiff(t, bin, store, tc.before, tc.after)
401				if code == 0 {
402					t.Fatal("diff must exit non-zero for a missing report")
403				}
404				if !strings.Contains(stderr, "not found") {
405					t.Fatalf("stderr must report a missing report:\n%s", stderr)
406				}
407				if stdout != "" {
408					t.Fatalf("stdout must be empty on failure, got:\n%s", stdout)
409				}
410				if strings.Contains(stdout, existing.ReportID) || strings.Contains(stdout, "results") ||
411					strings.Contains(stdout, "summary") || strings.Contains(stdout, contractsentinel.StatusUnchecked) {
412					t.Fatalf("stdout must not leak a partial result or the first report:\n%s", stdout)
413				}
414			})
415		}
416	}
417	
418	// 归档目录不存在时按“报告未找到”失败，且不得顺手创建目录。
419	func TestCLIDiffMissingStoreCreatesNothing(t *testing.T) {
420		bin := auditBinary(t)
